return ['domain'=>'gtfs-timetables','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'uk','project-id-version'=>'GTFS Timetables 0.1.0','pot-creation-date'=>'2026-10-23T19:11:43+00:00','po-revision-date'=>'2026-10-23T20:55:33+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['GTFS Timetables'=>'Розклади GTFS','Shows public transport schedules from a GTFS feed.'=>'Відображає розклади громадського транспорту з фіду GTFS.','PUBLICTRANSITDATA.NET'=>'PUBLICTRANSITDATA.NET','The file is larger than this site accepts (%s). Import it from a URL or with WP-CLI instead.'=>'Файл більший, ніж дозволяє цей сайт (%s). Імпортуйте його використовуючи посилання на нього або через WP-CLI.','Choose a GTFS .zip file first.'=>'Спершу виберіть файл GTFS у форматі .zip.','The upload failed (PHP error %d).'=>'Не вдалося завантажити файл (помилка PHP %d).','The file is not a .zip archive. A GTFS feed is published as a .zip of .txt files.'=>'Файл не є архівом .zip. Фід GTFS має бути фалом .zip з файлами .txt.','You are not allowed to import feeds.'=>'У вас немає прав на імпорт фідів.','Feed URL'=>'Посилання на фід','Link to the GTFS .zip published by the transport operator.'=>'Посилання на архів GTFS .zip, який публікує перевізник чи оператор.','Update automatically'=>'Оновлювати автоматично','Runs at night through WP-Cron. On sites with little traffic, set up a real cron job for wp-cron.php or use WP-CLI: wp gtfs-timetables import'=>'Запускається вночі через WP-Cron. На сайтах із невеликою відвідуваністю налаштуйте справжнє завдання cron для wp-cron.php або використовуйте WP-CLI: wp gtfs-timetables import','Data source credit'=>'Джерело даних','Shown under timetables. Many open data licences require crediting the publisher, e.g. "Data: City transport authority, CC BY 4.0". Leave empty to show nothing.'=>'Відображається під розкладами. Деякі ліцензії відкритих даних вимагають зазначати джерело, наприклад «Дані: міське управління транспорту, CC BY 4.0». Залиште порожнім, щоб нічого не відображати.','Import'=>'Імпорт','Current data imported %1$s. Feed time zone: %2$s.'=>'Поточні дані імпортовано %1$s. Часовий пояс фіду: %2$s.','This feed describes some trips with frequencies.txt ("every 10 minutes"). Those trips are not shown yet.'=>'Частину рейсів у цьому фіді описано через frequencies.txt («кожні 10 хвилин»). Такі рейси поки не відображаються.','Uploading the file…'=>'Завантаження файлу…','Import from feed URL'=>'Імпортувати за посиланням','Or upload a GTFS .zip file:'=>'Або завантажте файл GTFS .zip:','Upload and import'=>'Завантажити й імпортувати','Maximum file size: %s. For larger feeds use the feed URL or WP-CLI: wp gtfs-timetables import --file=feed.zip'=>'Максимальний розмір файлу: %s. Для більших фідів використовуйте посилання або WP-CLI: wp gtfs-timetables import --file=feed.zip','Automatic updates import from the feed URL and will replace data from an uploaded file.'=>'Автоматичне оновлення імпортує фід за посиланням і замінить дані із завантаженого файлу.','Re-import even if the feed has not changed'=>'Імпортувати повторно, навіть якщо фід не змінився','Find a stop'=>'Пошук зупинки','Stop name, code or id'=>'Назва, код або ID зупинки','Search'=>'Шукати','No stops found.'=>'Зупинок не знайдено.','Stop'=>'Зупинка','Code'=>'Код','Shortcodes'=>'Скорочення','station, includes all its platforms'=>'станція, разом з усіма її платформами','%s has no header row.'=>'У файлі %s немає рядка заголовків.','Could not download the feed: %s'=>'Не вдалося завантажити фід: %s','filesystem is not writable'=>'немає прав на запис у файлову систему','Could not unpack the feed: %s'=>'Не вдалося розпакувати фід: %s','The feed is missing required files: %s'=>'У фіді бракує обов\'язкових файлів: %s','Line %s'=>'Лінія %s','GTFS Timetables: no feed has been imported yet.'=>'Розклади GTFS: фід ще не імпортовано.','GTFS Timetables: the feed has no lines of the chosen transport modes.'=>'Розклади GTFS: у фіді немає ліній вибраних видів транспорту.','This line is not in the current timetable. Choose a line:'=>'Цієї лінії немає в чинному розкладі. Виберіть лінію:','GTFS Timetables: there is no stop with id "%s" in the feed.'=>'Розклади GTFS: у фіді немає зупинки з ID «%s».','Could not write to %1$s: %2$s'=>'Не вдалося записати в %1$s: %2$s','Another import is running. Try again when it has finished.'=>'Уже триває інший імпорт. Спробуйте знову, коли він завершиться.','Unpacking the feed…'=>'Розпакування фіду…','Downloading the feed…'=>'Завантаження фіду…','Importing %1$s: %2$d%% (%3$s rows so far)'=>'Імпорт %1$s: %2$d%% (оброблено рядків: %3$s)','Finishing…'=>'Завершення…','No import has run yet.'=>'Імпорт ще не запускався.','The feed has not changed since the last import.'=>'Фід не змінився з останнього імпорту.','Set the feed URL first.'=>'Спершу вкажіть посилання на фід.','The feed has no usable stop times.'=>'У фіді немає придатних часів відправлення.','Import finished: %1$s stops, %2$s trips, %3$s stop times.'=>'Імпорт завершено. Зупинок: %1$s, рейсів: %2$s, відправлень: %3$s.','Night lines'=>'Нічні лінії','Metro'=>'Метро','Trams'=>'Трамваї','Trolleybuses'=>'Тролейбуси','Buses'=>'Автобуси','Trains'=>'Поїзди','Ferries'=>'Пороми','Cable cars and funiculars'=>'Канатні дороги й фунікулери','Other lines'=>'Інші лінії','now'=>'зараз','in %d min'=>'через %d хв' . "\0" . 'через %d хв' . "\0" . 'через %d хв','Manual only'=>'Лише вручну','Daily'=>'Щодня','Weekly'=>'Щотижня','No departures scheduled.'=>'Відправлень не заплановано.','Line'=>'Маршрут','Direction'=>'Напрямок','Departs'=>'Відправлення','Choose a day'=>'Оберіть день','Previous day'=>'Попередній день','Next day'=>'Наступний день','No departures on this day.'=>'Цього дня відправлень немає.','block titleLine timetable'=>'Розклад лінії','block descriptionThe line a visitor chose in a Lines block. Put it on one page: every Lines block on the site links there.'=>'Лінія, яку відвідувач вибрав у блоці «Лінії». Додайте його на одну сторінку: усі блоки «Лінії» на сайті ведуть туди.','block keywordroute'=>'маршрут','block keywordtimetable'=>'розклад','block keywordGTFS'=>'GTFS','block titleLines'=>'Лінії','block descriptionAll lines of the network, grouped by transport mode.'=>'Усі лінії мережі, згруповані за видом транспорту.','block keywordroutes'=>'маршрути','block keywordnetwork'=>'мережа']];